        <label class="dokan-w3 dokan-control-label" for="dokan_custom_funnel_id">
            Unique Funnel Identifier
            <span class="dokan-tooltips-help" data-placement="bottom" data-original-title="Enter unique text for your funnel link. Must be letters, numbers, or dashes.">
                <i class="fas fa-question-circle"></i>
            </span>
        </label>
        <div class="dokan-w5 dokan-text-left">
            <input type="text" id="dokan_custom_funnel_id" name="dokan_custom_funnel_id" value="" class="dokan-form-control" placeholder="e.g., my-vip-store" onkeyup="updateFunnelPreview(this.value)">
            
            <div style="margin-top: 12px; background: #f0f0f1; padding: 10px; border-radius: 4px; display: flex; align-items: center; border: 1px solid #ddd;">
                <code id="funnel_url_preview" style="flex-grow: 1; word-break: break-all; background: transparent; padding: 0; color: #333;">
                    https://zzmore.store/store/z-zmore-open-market/?funnel=YOUR_IDENTIFIER                </code>
                <button type="button" class="dokan-btn dokan-btn-default dokan-btn-sm" onclick="copyFunnelUrl()" style="margin-left: 10px; white-space: nowrap;">
                    <i class="fas fa-copy"></i> Copy
                </button>
            </div>
            
            <span id="copy_success_msg" style="color: #00a32a; font-size: 13px; font-weight: bold; display: none; margin-top: 5px;">Copied to clipboard!</span>
        </div>
    </div>

    <script>
    function updateFunnelPreview(val) {
        // Use the vendor's store URL as the base in JavaScript
        var baseUrl = "https://zzmore.store/store/z-zmore-open-market/?funnel=";
        var sanitizedVal = val.toLowerCase().replace(/[^a-z0-9\-]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
        var displayVal = sanitizedVal ? sanitizedVal : 'YOUR_IDENTIFIER';
        document.getElementById('funnel_url_preview').innerText = baseUrl + displayVal;
    }

    function copyFunnelUrl() {
        var textToCopy = document.getElementById('funnel_url_preview').innerText;
        navigator.clipboard.writeText(textToCopy).then(function() {
            var msg = document.getElementById('copy_success_msg');
            msg.style.display = 'block';
            setTimeout(function() { msg.style.display = 'none'; }, 2500);
        });
    }
    </script>
