}

/* 6. Section Headings */
.woocommerce-checkout h3, 
#order_review_heading,
.woocommerce-order-details__title {
    color: #333;
    border-bottom: 3px solid var(--zz-brand);
    display: inline-block;
    padding-bottom: 5px;
    margin-bottom: 20px;
}

