    text-shadow: none !important;
}

/* Ensure the text stays black even when hovering */
.dokan-dashboard-wrap .dokan-btn-theme:hover {
    background-color: #d1690f !important; /* Slightly darker orange for hover effect */
    color: #000000 !important;
}

/* ==========================================================
   WooCommerce Thank You & Order Details Page Styling
   Brand Color: #e67e14
   ========================================================== */

/* 1. The "Thank You" / Order Received Message */
.woocommerce-checkout .woocommerce-thankyou-order-received {
    background-color: rgba(230, 126, 20, 0.1); /* Very light brand orange background */
    border-left: 5px solid #e67e14;
    padding: 15px 20px;
    color: #333;
    font-weight: 500;
    border-radius: 4px;
    margin-bottom: 30px;
}

/* 2. Order Overview List (Order number, date, total, etc.) */
ul.woocommerce-order-overview {
    display: flex;
    flex-wrap: wrap;
    gap: 15px;
    background: #f9f9f9;
    padding: 20px;
    border-top: 3px solid #e67e14;
    border-radius: 5px;
    list-style: none;
    margin-bottom: 40px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.03);
}

ul.woocommerce-order-overview li {
    border-right: 1px solid #ddd;
    padding-right: 20px;
    margin-right: 0;
    text-transform: uppercase;
    font-size: 0.85em;
    color: #666;
}

ul.woocommerce-order-overview li:last-child {
    border-right: none;
}

ul.woocommerce-order-overview li strong {
    display: block;
    font-size: 1.2em;
    color: #333;
    margin-top: 5px;
    text-transform: none;
}

/* 3. Section Headings (e.g., "Order details", "Customer details") */
.woocommerce-order h2 {
    color: #e67e14;
    font-size: 1.5em;
    margin-bottom: 15px;
    border-bottom: 2px solid #eee;
    padding-bottom: 10px;
}

/* 4. Order Details Table */
table.woocommerce-table--order-details {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 40px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
    background: #fff;
    border-radius: 5px;
    overflow: hidden;
}

table.woocommerce-table--order-details th,
table.woocommerce-table--order-details td {
    padding: 15px;
    border: 1px solid #eee;
    text-align: left;
}

table.woocommerce-table--order-details thead th {
    background-color: #f7f7f7;
    color: #333;
    text-transform: uppercase;
    font-size: 0.9em;
}

/* Align table footers (Subtotal, Shipping, Total) to the right */
table.woocommerce-table--order-details tfoot th {
    text-align: right;
    font-weight: normal;
}

/* Highlight the final Total row */
table.woocommerce-table--order-details tfoot tr:last-child th,
table.woocommerce-table--order-details tfoot tr:last-child td {
    background-color: rgba(230, 126, 20, 0.05);
    font-weight: bold;
    color: #e67e14;
    font-size: 1.1em;
}

/* 5. Customer Details & Address Boxes */
.woocommerce-customer-details {
    background: #fdfdfd;
    border: 1px solid #eee;
    padding: 20px;
    border-radius: 5px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.02);
}

.woocommerce-customer-details address {
    font-style: normal;
    line-height: 1.6;
    color: #555;
    margin-top: 10px;
}

/* 6. Links and Buttons in the Order Area */
.woocommerce-order a {
    color: #e67e14;
    text-decoration: none;
    transition: color 0.2s ease;
}

.woocommerce-order a:hover {
    color: #cc6d0d; /* Slightly darker shade for hover */
    text-decoration: underline;
}

.woocommerce-order .button {
    background-color: #e67e14;
    color: #fff;
    border-radius: 4px;
    padding: 10px 20px;
    border: none;
    font-weight: bold;
    transition: background-color 0.2s ease;
}

.woocommerce-order .button:hover {
    background-color: #cc6d0d;
    color: #fff;
}

/* Responsive Fix for Order Overview List */
@media (max-width: 768px) {
    ul.woocommerce-order-overview {
        flex-direction: column;
        gap: 10px;
    }
    ul.woocommerce-order-overview li {
        border-right: none;
        border-bottom: 1px solid #ddd;
        padding-bottom: 10px;
    }
    ul.woocommerce-order-overview li:last-child {
        border-bottom: none;
    }
}
/* Force Ultimate Elementor Side Cart to stay in viewport */
.uael-side-cart-wrapper,
.uael-side-cart-offcanvas,
.elementor-widget-uael-woo-mini-cart .uael-side-cart {
    position: fixed !important;
    top: 0 !important;
    height: 100vh !important; /* Forces it to take up the screen height, not document height */
    z-index: 999999 !important; /* Ensures it stays on top of everything */
}

/* Ensure the overlay covers the screen, not the top of the page */
.uael-side-cart-overlay {
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    z-index: 999998 !important;
}

/* 1) Reduce the page H1 (overrides inline style) */
.ordafy-store-category-wrapper > div > h1 {
  font-size: clamp(1.4rem, 3vw, 1.9rem) !important;
  line-height: 1.2 !important;
  margin-bottom: 10px !important;
}

/* 2) Show the full store banner image (remove cropping) */
.ordafy-store-category-wrapper .dokan-single-seller .store-banner {
  height: auto !important;
  overflow: visible !important;
}

.ordafy-store-category-wrapper .dokan-single-seller .store-banner img {
  width: 100% !important;
  height: auto !important;
  max-height: none !important;
  object-fit: contain !important;
  object-position: center !important;
  display: block !important;
  transform: none !important; /* disables the zoom crop effect */
}

.etn-event-search-wrapper .search-button-wrapper button.etn-filter-icon {
    background-color: #000000 !important;
    color: #ffffff;
    border: none;
}

h4.etn-organizer-name {
    display: none !important;
}


.dls-product-table td:nth-child(1) {
    width: 56px !important;
    text-align: center !important;
}

.dls-product-table th:nth-child(2),
.dls-product-table td:nth-child(2) {
    width: 92px !important;
}

.dls-product-table th:nth-child(4),
.dls-product-table td:nth-child(4),
.dls-product-table th:nth-child(5),
.dls-product-table td:nth-child(5) {
