/* --- Mobile Styles --- */
@media (max-width: 767px) {
    .dls-product-tools {
        flex-direction: column !important;
        gap: 12px !important;
    }

    .dls-product-search,
    .dls-product-filter {
        width: 100% !important;
    }
}
</style>
