    <script>
        document.addEventListener('DOMContentLoaded', function() {
            var forms = document.querySelectorAll('.tee-header-search-form');
            forms.forEach(function(form) {
                form.addEventListener('submit', function(e) {
                    var searchInput = form.querySelector('.tee-header-search-input').value.trim();
                    var catSelect = form.querySelector('.tee-header-cat-select');
                    var selectedOption = catSelect.options[catSelect.selectedIndex];
                    
                    // If no keyword is entered
                    if (searchInput === '') {
                        e.preventDefault(); // Stop the standard form submission
                        
                        var catUrl = selectedOption.getAttribute('data-url');
                        
                        if (catUrl) {
                            // A specific category is selected -> Go directly to the category page
                            window.location.href = catUrl;
                        } else {
                            // "All Categories" is selected -> Go directly to the main shop page
                            window.location.href = 'https://zzmore.store/shop/';
                        }
                    }
                });
            });
        });
    </script>

    <style>
        .tee-header-search-wrapper {
            width: 100%;
            max-width: 700px;
            margin: 0 auto;
        }
        
        /* Unified Bar Design */
        .tee-header-search-form {
            display: flex;
            align-items: center;
            width: 100%;
            height: 46px;
            border: 2px solid #e67e14;
            border-radius: 8px;
            background: #ffffff;
            overflow: hidden;
            transition: box-shadow 0.3s ease;
        }
        
        .tee-header-search-form:focus-within {
            box-shadow: 0 0 0 3px rgba(230, 126, 20, 0.15);
        }
        
        /* Search Input */
        .tee-header-search-input {
            flex-grow: 1;
            flex-shrink: 1;
            height: 100%;
            border: none !important;
            outline: none !important;
            padding: 0 16px !important;
            font-size: 14px !important;
            color: #333 !important;
            background: transparent !important;
            box-shadow: none !important;
            min-width: 80px; 
        }
        
        /* Category Wrapper & Select */
        .tee-header-cat-wrapper {
            height: 100%;
            border-left: 1px solid #e0e0e0;
            background: #fdfdfd;
            flex-shrink: 0; /* Prevents the dropdown from being crushed */
        }
        
        .tee-header-cat-select {
            height: 100%;
            width: 100%;
            max-width: 220px; 
            border: none !important;
            outline: none !important;
            background: transparent !important;
            padding: 0 30px 0 12px !important;
            font-size: 14px !important;
            color: #555 !important;
            cursor: pointer;
            box-shadow: none !important;
            -webkit-appearance: auto;
            appearance: auto;
            
            /* Truncate text cleanly if a category name is too long */
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        
        /* Submit Button */
        .tee-header-search-btn {
            height: 100%;
            background: #e67e14 !important;
            border: none !important;
            color: #ffffff !important;
            padding: 0 24px !important;
            font-size: 14px !important;
            font-weight: 600 !important;
            cursor: pointer !important;
            transition: background 0.3s ease, color 0.3s ease !important;
            margin: 0 !important;
            border-radius: 0 !important;
            flex-shrink: 0;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        
        .tee-header-search-btn:hover {
            background: #000000 !important;
            color: #ffffff !important;
        }

        .tee-search-icon {
            display: none; /* Hidden on desktop */
            width: 16px;
            height: 16px;
            fill: currentColor;
        }

        /* Mobile Responsiveness */
        @media (max-width: 768px) {
            .tee-header-cat-select {
                max-width: 135px; /* Ensures "All Categories" fits perfectly */
                padding: 0 20px 0 8px !important;
                font-size: 13px !important;
            }
            .tee-header-search-btn {
                padding: 0 16px !important; /* Shrink button width */
            }
            .tee-header-search-input {
                font-size: 13px !important;
                padding: 0 10px !important;
            }
            .tee-search-text {
                display: none; /* Hide the word 'Search' */
            }
            .tee-search-icon {
                display: block; /* Show the magnifying glass */
            }
        }
    </style>
