<script type='text/javascript' id='unlimited-elements-scripts'>

/* Woo Mini Cart scripts: */ 

jQuery(document).ready(function(){
function uc_woo_mini_cart_ax_elementor_6abf54d_start(){
			
  
  var objWidget = jQuery("#uc_woo_mini_cart_ax_elementor_6abf54d");
  var shopPageUrl = "https://zzmore.store/shop/";
    
  var objMinicart = new ueMiniCart();

  objMinicart.init(objWidget, shopPageUrl);

  var miniCartElement = objWidget.find(".ue-mini-cart");
  var miniCartCloseButton = objWidget.find(".ue_cart_close_button");
  var miniCartToggleButton = objWidget.find(".ue_mini_cart_toggle");
  var bodyElement = jQuery("body");

  var miniCartFadeInOutDuration = 1;
  var miniCartHideDelay = 1;

  /**
  * fade in
  */
  function miniCartFadeIn(){  
    miniCartElement.fadeIn(miniCartFadeInOutDuration);  
  }

  /**
  * fade out
  */
  function miniCartFadeOut(){  
    miniCartElement.stop().fadeOut(miniCartFadeInOutDuration);  
  }

     

   
       
      // Show/hide the mini cart on click
      miniCartToggleButton.click(function() {
        miniCartElement.fadeToggle(miniCartFadeInOutDuration);
      });

      // Show/hide the mini cart on added to cart
      bodyElement.on("added_to_cart", miniCartFadeIn);
    

   //close mini cart
   miniCartCloseButton.on("click", miniCartFadeOut); 
    
}if(jQuery("#uc_woo_mini_cart_ax_elementor_6abf54d").length && !jQuery("#uc_woo_mini_cart_ax_elementor_6abf54d").parents('[data-elementor-type="popup"]').length) uc_woo_mini_cart_ax_elementor_6abf54d_start();
	jQuery( document ).on( 'elementor/popup/show', (event, id, objPopup) => {
	if(objPopup.$element.has(jQuery("#uc_woo_mini_cart_ax_elementor_6abf54d")).length) uc_woo_mini_cart_ax_elementor_6abf54d_start()});
});
			
</script>
		<style>
			.unlimited-elements-background-overlay{
				position:absolute;
				top:0px;
				left:0px;
				width:100%;
				height:100%;
				z-index:0;
			}

			.unlimited-elements-background-overlay.uc-bg-front{
				z-index:999;
			}
		</style>

		<script type='text/javascript'>

			jQuery(document).ready(function(){
					
				function ucBackgroundOverlayPutStart(){
				
					var objBG = jQuery(".unlimited-elements-background-overlay").not(".uc-bg-attached");

					if(objBG.length == 0)
						return(false);

					objBG.each(function(index, bgElement){

						var objBgElement = jQuery(bgElement);

						var targetID = objBgElement.data("forid");

						var location = objBgElement.data("location");

						switch(location){
							case "body":
							case "body_front":
								var objTarget = jQuery("body");
							break;
							case "layout":
							case "layout_front":
								var objLayout = jQuery("*[data-id=\""+targetID+"\"]");
								var objTarget = objLayout.parents(".elementor");
								if(objTarget.length > 1)
									objTarget = jQuery(objTarget[0]);
							break;
							default:
								var objTarget = jQuery("*[data-id=\""+targetID+"\"]");
							break;
						}


						if(objTarget.length == 0)
							return(true);

						var objVideoContainer = objTarget.children(".elementor-background-video-container");

						if(objVideoContainer.length == 1)
							objBgElement.detach().insertAfter(objVideoContainer).show();
						else
							objBgElement.detach().prependTo(objTarget).show();


						var objTemplate = objBgElement.children("template");

						if(objTemplate.length){
							
					        var clonedContent = objTemplate[0].content.cloneNode(true);

					    	var objScripts = jQuery(clonedContent).find("script");
					    	if(objScripts.length)
					    		objScripts.attr("type","text/javascript");
					        
					        objBgElement.append(clonedContent);
							
							objTemplate.remove();
						}

						objBgElement.trigger("bg_attached");
						objBgElement.addClass("uc-bg-attached");

					});
				}

				ucBackgroundOverlayPutStart();

				jQuery( document ).on( 'elementor/popup/show', ucBackgroundOverlayPutStart);
				jQuery( "body" ).on( 'uc_dom_updated', ucBackgroundOverlayPutStart);

			});


		</script>
